package main

import (
 "bytes"
 "context"
 "encoding/json"
 "errors"
 "fmt"
 "net/http"
 "io"
 "time"
)
var erroredUpstream=errors.New("errored upstream")
type paymentGatewayPostPaymentRequest struct { Amount int `json:"amount"` }
var paymentClient=&http.Client{Transport:&http.Transport{MaxIdleConns:512,MaxIdleConnsPerHost:512,IdleConnTimeout:90*time.Second},Timeout:5*time.Second}
func requestPaymentGatewayPostPayment(ctx context.Context,url,token string,param *paymentGatewayPostPaymentRequest,key string,_ func()([]Ride,error)) error {
 b,err:=json.Marshal(param);if err!=nil{return err}
 for retry:=0;retry<10;retry++ {
  req,err:=http.NewRequestWithContext(ctx,"POST",url+"/payments",bytes.NewReader(b));if err!=nil{return err}
  req.Header.Set("Content-Type","application/json");req.Header.Set("Authorization","Bearer "+token);req.Header.Set("Idempotency-Key",key)
  res,e:=paymentClient.Do(req)
  if e==nil {io.Copy(io.Discard,res.Body);res.Body.Close();if res.StatusCode==204{return nil};err=fmt.Errorf("payment status %d",res.StatusCode)} else {err=e}
  select {case <-ctx.Done():return ctx.Err();case <-time.After(10*time.Millisecond):}
 }
 return fmt.Errorf("%w: %v",erroredUpstream,err)
}
