 stateMu.Lock();defer stateMu.Unlock();if c:=liveChairs[id];c!=nil {if c.HasLocation {c.Distance+=calculateDistance(c.Location.Latitude,c.Location.Longitude,p.Latitude,p.Longitude)};c.Location=ChairLocation{ChairID:id,Latitude:p.Latitude,Longitude:p.Longitude,CreatedAt:now};c.HasLocation=true}
}
func isAvailable(id string) bool {
